import {schools,themes,uid,allLessons,questionCount,trainingQuestions} from './data.js';
import {schoolPlanets,planetSchool,planetVisual,courseInSchool} from './cosmos.js';
import {solarHome,journey,schoolHero,skyDetails} from './cosmos-view.js';
import {installPlanetFlights} from './planet-flight.js';
import {loadData,saveData,putFile,getFile,deleteFile} from './storage.js';
import {session,canEdit,isOwner,loadLibrary,saveLibrary,restoreLibrary,api,uploadPdf,fetchPdf} from './api-client.js';

const previousLocalLibrary=localStorage.getItem('orbita-school-v1');
let data=loadData();
let studyProfileUnavailable=false;
let quiz=null, draft=null, lessonDraft=null, viewer=null, lastFocus=null, toastTimer;
const adminActions=new Set(['save-course-navigation','discard-course-navigation','new-subject','edit-subject','delete-subject','confirm-delete-subject','new-course','delete-course','confirm-delete-course','add-module','remove-module','confirm-remove-module','add-lesson','edit-lesson','remove-lesson','confirm-remove-lesson','add-question','remove-question','remove-attachment','remove-pending-file','export','confirm-import','remove-teacher','confirm-remove-teacher','migrate-legacy','confirm-migrate-legacy']);
const app=document.querySelector('#app'), overlay=document.querySelector('#overlay');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeTheme=t=>Object.hasOwn(themes,t)?t:'purple';
const getCourse=id=>data.courses.find(c=>c.id===id);
const getSubject=id=>data.subjects.find(s=>s.id===id);
const schoolById=id=>{const p=planetSchool(id);const original=schools.find(s=>s.id===id)||schools[0];return p?{...original,...p,desc:p.description,theme:({mars:'peach',jupiter:'peach',saturn:'purple',uranus:'blue',neptune:'purple'})[p.planet],icon:'planet'}:original;};
let activeSchoolId=sessionStorage.getItem('orbita-active-school')||'';
const progress=c=>allLessons(c).filter(l=>data.progress[c.id]?.includes(l.id)).length;
const normalize=v=>String(v).trim().toLocaleLowerCase('ru').replace(/ё/g,'е');
const slugPath=s=>encodeURIComponent(s);
const cacheData=()=>saveData(data,{keepGuestLearning:!!session.user});
function persist(){if(!cacheData()){toast('Не удалось сохранить данные в браузере.');return false;}return true;}
let librarySaving=false;
async function persistLibrary(){
 if(librarySaving){toast('Сохранение уже выполняется.');return false;}
 librarySaving=true;
 try{await saveLibrary(data);cacheData();return true;}
 catch(e){restoreLibrary(data);toast(e.message);return false;}
 finally{librarySaving=false;}
}
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
function icon(name,size=22,cls=''){
 const paths={
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m5 9 7 7 7-7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',user:'<circle cx="12" cy="8" r="3.5"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14v6Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',book:'<path d="M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-2-1-6-2-10 1Zm0 0v15"/>',file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h8"/>',slides:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M12 16v6m-5 0 5-4 5 4M8 8h8m-8 3h5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',heart:'<path d="M12 21S2 14 2 7a5 5 0 0 1 10-1A5 5 0 0 1 22 7c0 7-10 14-10 14Z"/>',sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Zm8-2v4m-2-2h4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>',play:'<path d="m8 4 13 8-13 8V4Z"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5M14 4l-4 16"/>',math:'<path d="M4 7h6M7 4v6m7-3h6M4 17h6m4-2h6m-6 4h6M5 15l4 4m0-4-4 4"/>',letters:'<path d="m2 19 6-15 6 15M4 14h8m5-3h4m-1-4v12m-3 0h6"/>',robot:'<rect x="3" y="7" width="18" height="13" rx="4"/><path d="M12 3v4m-3 9h6M1 11v5m22-5v5"/><circle cx="8" cy="12" r="1"/><circle cx="16" cy="12" r="1"/><circle cx="12" cy="2" r="1"/>',globe:'<circle cx="12" cy="12" r="10"/><ellipse cx="12" cy="12" rx="4" ry="10"/><path d="M2 12h20M4 6h16M4 18h16"/>',atom:'<ellipse cx="12" cy="12" rx="11" ry="4"/><ellipse cx="12" cy="12" rx="11" ry="4" transform="rotate(60 12 12)"/><ellipse cx="12" cy="12" rx="11" ry="4" transform="rotate(-60 12 12)"/><circle cx="12" cy="12" r="1"/>',planet:'<circle cx="12" cy="12" r="7"/><ellipse cx="12" cy="12" rx="13" ry="4" transform="rotate(-30 12 12)"/><path d="m4 3 1 1m16 15 1 1M17 3h2"/>',rocket:'<path d="M8 16C4 9 12 1 21 3c1 9-6 16-13 13ZM8 16l-4 4m5-3-1 5M7 14l-5 1m3-5 1-5 6-1m4 9 4 1-1 5-5 1"/><circle cx="15" cy="8" r="2"/>',telescope:'<path d="m3 9 15-7 4 9-16 5-3-7Zm9 5v8m0-5-5 5m5-5 5 5M17 3l4 9M6 8l3 7"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1 3-6Z"/><path d="M9 11v1m6-1v1m-6 2q3 3 6 0"/>',trophy:'<path d="M7 3h10v7a5 5 0 0 1-10 0V3Zm0 2H2v3a5 5 0 0 0 5 5m10-8h5v3a5 5 0 0 1-5 5M12 15v5m-5 2h10"/>'
 };
 return `<svg class="${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;
}
function logo(){return `<svg width="40" height="40" viewBox="0 0 44 44" fill="none" aria-hidden="true"><circle cx="22" cy="22" r="10" fill="#f1cf94"/><ellipse cx="22" cy="22" rx="21" ry="7.5" transform="rotate(-35 22 22)" stroke="#f1cf94" stroke-width="2"/><circle cx="36" cy="11" r="3.7" fill="#98cbe3"/></svg>`;}
const brand=()=>`<a href="#/" class="brand" aria-label="${esc(data.platform)} — главная">${logo()}${esc(data.platform).toLowerCase()}</a>`;
function route(){return (location.hash.slice(1)||'/').split('/').filter(Boolean).map(x=>{try{return decodeURIComponent(x)}catch{return x}});}
function hrefSubject(school,subject,mode='courses'){return `#/subject/${slugPath(school)}/${slugPath(subject)}/${mode}`;}
function crumbs(items){return `<nav class="crumbs" aria-label="Хлебные крошки"><a href="#/">Главная</a>${items.map(([label,href])=>`<span aria-hidden="true">/</span>${href?`<a href="${href}">${esc(label)}</a>`:`<span aria-current="page">${esc(label)}</span>`}`).join('')}</nav>`;}
function notice(text){return `<div class="notice">${icon('info',19)}<span>${text}</span></div>`;}
function shell(content,active=''){
 const nav=[['schools','Школы','#/schools'],['courses','Курсы','#/catalog/courses'],['materials','Материалы','#/catalog/materials'],['trainer','Тренажёр','#/trainer'],['about','О платформе','#/about']];
 const links=nav.map(([key,title,url])=>`<a href="${url}" class="${active===key?'active':''}">${title}</a>`).join('');
 const isHome=!route()[0];
 return `<div class="cosmic-backdrop" aria-hidden="true">${skyDetails()}${!isHome&&planetSchool(activeSchoolId)&&['school','subject','course','lesson','materials','quiz','result'].includes(route()[0])?`<div class="planet-horizon">${planetVisual(document.documentElement.dataset.planet)}</div>`:''}</div><div class="container cosmic-shell"><header class="header">${brand()}${isHome?'<span class="header-caption">БЕСПЛАТНОЕ ОБРАЗОВАНИЕ · БЕЗГРАНИЧНЫЙ КОСМОС</span>':''}<nav class="nav" aria-label="Главная навигация">${links}</nav><div class="header-actions"><button class="icon-button" data-action="search" aria-label="Поиск по платформе">${icon('search',18)}</button><a class="btn light small" href="#/profile">${icon('user',16)}Моё обучение</a></div></header><nav class="mobile-nav" aria-label="Разделы">${links}</nav><main id="main" tabindex="-1">${content}</main><footer class="footer">${brand()}<p>Знания открыты. Возможности безграничны.</p><div class="footer-links"><a href="#/about">О платформе</a><a href="#/admin">Для преподавателей ${icon('arrow',12).replace('<svg','<svg style="display:inline;vertical-align:middle"')}</a><span>© ${new Date().getFullYear()} ${esc(data.platform)}</span></div></footer></div>`;
}
function fish(color='#e9c394'){return `<svg viewBox="0 0 100 55" fill="none" aria-hidden="true"><path d="M70 26 95 7c-2 18-1 24 2 39L70 31" fill="${color}" opacity=".8"/><path d="M20 18C25-4 49 1 57 15M33 42c10 16 23 10 25-2" fill="${color}" opacity=".65"/><path d="M4 28C15 5 53 4 76 27 54 53 17 50 4 28Z" fill="${color}"/><path d="M39 15c-11 11-8 23 1 29" stroke="#fff" stroke-opacity=".35" stroke-width="4"/><circle cx="18" cy="26" r="3" fill="#38314d"/><circle cx="17" cy="25" r="1" fill="white"/><path d="m47 25 14 5-12 6" fill="#fff" opacity=".3"/></svg>`;}
function space(){return `<div class="space-wrap"><div class="floating-label">${icon('sparkles',17)}Вселенная твоих возможностей</div><div class="space" data-action="ripple" aria-label="Космос с рыбками: нажмите, чтобы создать водные круги"><div class="orbit-line"></div><div class="orbit-line second"></div>${Array.from({length:34},(_,i)=>`<i class="star-dot" style="left:${(i*31+7)%98}%;top:${(i*23+9)%95}%;width:${i%4===0?3:2}px;height:${i%4===0?3:2}px;animation-delay:-${i%5}s"></i>`).join('')}<div class="small-planet"></div><div class="tiny-planet"></div><div class="planet-main"></div><div class="planet-ring"></div><button class="space-fish fish-one" data-action="fish" aria-label="Золотая космическая рыбка">${fish()}</button><button class="space-fish fish-two" data-action="fish" aria-label="Мятная космическая рыбка">${fish('#c7e5c3')}</button><button class="space-fish fish-three" data-action="fish" aria-label="Лиловая космическая рыбка">${fish('#d5bcf7')}</button><span class="space-note">${icon('target',12)}Нажми на рыбку — загадай открытие</span></div><div class="floating-label bottom">${icon('heart',17)}Бесплатно. Для каждого.</div></div>`;}
function schoolCards(){return journey();}

function courseCard(c,mode='courses'){
 const total=allLessons(c).length, done=progress(c), subj=getSubject(c.subject);
 return `<a class="course-card" href="#/${mode==='materials'?'materials':'course'}/${slugPath(c.id)}"><div class="course-art ${safeTheme(c.theme)}"><span class="tag">${esc(subj?.title||'Новый курс')}</span>${icon(c.icon,75,'art-icon')}<span class="art-symbol">${c.subject==='coding'?'{}':c.subject==='math'?'x²':'✧'}</span></div><div class="course-body"><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p><div class="course-info"><span>${icon('book',12).replace('<svg','<svg style="display:inline;vertical-align:middle"')} ${total} ${plural(total,'урок','урока','уроков')}</span><span>${esc(c.level)}</span></div>${done?`<div class="progress" aria-label="Завершено ${done} из ${total} уроков"><span style="width:${done/Math.max(1,total)*100}%"></span></div>`:''}<div class="course-footer"><span class="free">${icon('check',12)}Бесплатно</span><span>${mode==='materials'?'Смотреть материалы':done?'Продолжить учиться':'Начать открытие'} ${icon('arrow',14).replace('<svg','<svg style="display:inline;vertical-align:middle;margin-left:8px"')}</span></div></div></a>`;
}
function plural(n,a,b,c){return n%10===1&&n%100!==11?a:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?b:c;}
function home(){return shell(solarHome(data.platform));}

function schoolsPage(){return shell(`${crumbs([['Школы']])}<div class="page-heading school-map-heading"><div class="eyebrow">Карта твоей вселенной</div><h1>Выбери свою орбиту</h1><p>От первого школьного открытия до уверенности на ЕГЭ. Чем дальше от Солнца, тем глубже знания.</p></div>${journey()}`,'schools');}

function schoolPage(id){
 const s=schoolById(id);if(!planetSchool(id))return notFound();
 const subjects=data.subjects.filter(x=>x.schools.includes(s.id==='ege'?'senior':s.id));
 const cards=subjects.map(sub=>`<a class="subject-card ${safeTheme(sub.theme)}" href="${hrefSubject(s.id,sub.id)}" aria-label="${esc(sub.title)}. ${esc(sub.desc)}">
  <div class="flip-inner">
   <div class="flip-front">${icon(sub.icon,75)}<h3>${esc(sub.title)}</h3><p class="subject-summary">${esc(sub.desc)}</p><span class="text-button">Открыть ${icon('arrow',16)}</span></div>
   <div class="flip-back" aria-hidden="true"><h3>${esc(sub.title)}</h3><p>${esc(sub.desc)}</p><span class="text-button">Открыть ${icon('arrow',16)}</span></div>
  </div></a>`).join('');
 return shell(`${crumbs([['Планеты-школы','#/schools'],[s.title]])}${schoolHero(s)}<section class="school-subjects" aria-labelledby="school-subject-title"><div class="section-title"><div><h2 id="school-subject-title">Выбери предмет</h2></div></div>${cards?`<div class="subject-grid">${cards}</div>`:empty('Предметы скоро появятся','Загляни на другую планету, чтобы начать учиться.')}</section><nav class="neighbor-planets" aria-label="Другие планеты">${schoolPlanets.filter(p=>p.id!==s.id).map(p=>`<a href="#/school/${p.id}" data-flight-school="${p.id}">${planetVisual(p.planet)}<span>${p.title}<small>${p.name} · ${p.id==='ege'?'ЕГЭ':p.grades+' классы'}</small></span>${icon('arrow',14)}</a>`).join('')}</nav>`,'schools');
}

function subjectPage(schoolId,subjectId,mode='courses'){
 const s=schoolById(schoolId),sub=getSubject(subjectId);if(!sub)return notFound();
 const courses=data.courses.filter(c=>c.subject===sub.id&&courseInSchool(c,s.id)&&c.published);
 return shell(`${crumbs([[s.title,`#/school/${s.id}`],[sub.title]])}<div class="subject-hero ${safeTheme(sub.theme)}">${icon(sub.icon,80)}<div><span class="eyebrow">Планета ${s.name}</span><h1>${esc(sub.title)}</h1><p>${esc(sub.desc)}</p><span class="tag" style="margin-top:15px">${s.id==='ege'?'Подготовка к ЕГЭ':s.grades+' классы'}</span></div></div><nav class="tabs" aria-label="Формат обучения">${[['courses','Курсы'],['materials','Учебные материалы'],['trainer','Тренажёр']].map(([key,label])=>`<a class="tab ${mode===key?'active':''}" href="${hrefSubject(s.id,sub.id,key)}">${label}</a>`).join('')}</nav>${mode==='trainer'?trainerContent(s.id,sub.id):`<div class="section-title"><div><h2>${mode==='materials'?'Библиотека для твоих открытий':'От интереса к первым результатам'}</h2><p class="muted" style="margin-top:10px">${mode==='materials'?'Выбери большую тему, затем нужный урок. Пособия и презентации открываются прямо здесь.':'Теория, примеры и задания с проверкой — шаг за шагом.'}</p></div></div>${courses.length?`<div class="course-grid" style="margin-bottom:45px">${courses.map(c=>courseCard(c,mode)).join('')}</div>`:empty('Первые открытия ещё впереди','Для этой школы пока нет опубликованных курсов. Можно выбрать другую школу или добавить курс в редакторе.','Открыть редактор','#/admin')}`}`,'schools');
}
function empty(title,text,button='',href='#/'){return `<div class="empty">${icon('planet',55)}<h3>${esc(title)}</h3><p>${esc(text)}</p>${button?`<a class="btn secondary" href="${href}">${esc(button)} ${icon('arrow',15)}</a>`:''}</div>`;}
function catalog(mode='courses',preset=''){
 mode=mode==='materials'?'materials':'courses';
 return shell(`${crumbs([[mode==='materials'?'Учебные материалы':'Курсы']])}<div class="page-heading"><div class="eyebrow">Знания всегда рядом</div><h1>${mode==='materials'?'Библиотека открытий':'Найди своё новое увлечение'}</h1><p>${mode==='materials'?'Пособия, презентации и конспекты, к которым легко вернуться. Выбери курс, тему и урок.':'Понятная теория и практика с обратной связью. Каждый курс можно проходить в своём темпе.'}</p></div><div class="filters"><div class="search-field">${icon('search',18)}<input id="catalog-query" placeholder="Найти курс или тему" aria-label="Поиск курсов"></div><select id="catalog-school" aria-label="Школа"><option value="">Все классы</option>${schoolPlanets.map(s=>`<option value="${s.id}">${s.name} · ${s.id==='ege'?'ЕГЭ':s.grades+' классы'}</option>`).join('')}</select><select id="catalog-subject" aria-label="Направление"><option value="">Все направления</option>${data.subjects.map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')}</select><select id="catalog-level" aria-label="Уровень"><option value="">Все уровни</option><option ${preset==='ege'?'selected':''}>Подготовка к ЕГЭ</option><option>С нуля</option><option>Базовый</option><option>Первое знакомство</option></select></div><div id="catalog-results" data-mode="${mode}" style="margin-bottom:45px">${catalogResults(mode,'','','',preset==='ege'?'Подготовка к ЕГЭ':'')}</div>`,mode);
}
function catalogResults(mode,query='',school='',subject='',level=''){
 const courses=data.courses.filter(c=>c.published&&(!school||courseInSchool(c,school))&&(!subject||c.subject===subject)&&(!level||c.level===level)&&normalize(c.title+' '+c.desc+' '+allLessons(c).map(l=>l.title).join(' ')).includes(normalize(query)));
 return `<p class="muted small margin-bottom">${courses.length} ${plural(courses.length,'курс','курса','курсов')}</p>${courses.length?`<div class="course-grid">${courses.map(c=>courseCard(c,mode)).join('')}</div>`:empty('Пока ничего не нашлось','Попробуй изменить запрос или выбрать другие фильтры.')}`;
}
function curriculum(c,mode='course'){
 let n=0;return c.modules.map((m,i)=>`<details class="module" open><summary><span>${String(i+1).padStart(2,'0')} · ${esc(m.title)}</span><span>${m.lessons.length} ${plural(m.lessons.length,'урок','урока','уроков')}${icon('down',14)}</span></summary>${m.lessons.map(l=>{n++;return `<a class="lesson-row" href="${mode==='materials'?`#/materials/${slugPath(c.id)}/${slugPath(l.id)}`:`#/lesson/${slugPath(c.id)}/${slugPath(l.id)}`}" ${mode==='materials'?'data-action="material-lesson"':''}><span class="number ${data.progress[c.id]?.includes(l.id)?'done':''}">${data.progress[c.id]?.includes(l.id)?icon('check',13):n}</span><span>${esc(l.title)}</span>${icon('chevron',14)}</a>`}).join('')}${!m.lessons.length?'<p class="muted small" style="padding:15px 20px">В этой теме пока нет уроков.</p>':''}</details>`).join('');
}
function coursePage(id){const c=getCourse(id);if(!c||!c.published)return notFound();const subject=getSubject(c.subject),lessons=allLessons(c),done=progress(c),next=lessons.find(l=>!data.progress[c.id]?.includes(l.id))||lessons[0];return shell(`${crumbs([['Курсы','#/catalog/courses'],[c.title]])}<div class="course-layout"><div><section class="course-overview ${safeTheme(c.theme)}">${icon(c.icon,70)}<span class="tag">${esc(subject?.title)} · ${esc(c.level)}</span><h1>${esc(c.title)}</h1><p>${esc(c.desc)}</p><div class="course-stats"><span>${lessons.length} ${plural(lessons.length,'урок','урока','уроков')}</span><span>${questionCount(c)} ${plural(questionCount(c),'задание','задания','заданий')}</span><span>Без дедлайнов</span><span>Бесплатно</span></div></section><h2 style="font-size:24px;margin:28px 0 20px">Твой маршрут обучения</h2>${curriculum(c)}${!lessons.length?empty('Курс только начинается','Преподаватель скоро добавит первые уроки.'):''}</div><aside class="panel sticky"><h3>Начни с любопытства</h3><p class="muted small">Короткая теория, понятные примеры и задания, которые закрепляют знания.</p><div style="margin:24px 0"><div class="row small"><span>Твой прогресс</span><strong class="end">${done} / ${lessons.length}</strong></div><div class="progress"><span style="width:${done/Math.max(1,lessons.length)*100}%"></span></div></div>${next?`<a class="btn wide" href="#/lesson/${slugPath(c.id)}/${slugPath(next.id)}">${done?'Продолжить обучение':'Начать учиться'} ${icon('arrow',16)}</a>`:''}<a class="btn secondary wide" style="margin-top:12px" href="#/materials/${slugPath(c.id)}">${icon('book',17)}Учебные материалы</a><p class="free" style="margin-top:20px">${icon('heart',14)}Каждый урок открыт для тебя</p></aside></div>`,'courses');}
function prose(text){return String(text).split(/```(?:[\w+#-]*)\n?/g).map((part,i)=>i%2?`<pre><code>${esc(part.trim())}</code></pre>`:part.split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('')).join('');}
function questionInput(q,index,answer='',prefix='q'){
 return q.type==='choice'?`<div class="options">${q.options.map((o,i)=>`<label class="option"><input type="radio" name="${prefix}${index}" value="${esc(o)}" ${answer===o?'checked':''} required><span>${esc(o)}</span></label>`).join('')}</div>`:`<input class="answer-input" name="${prefix}${index}" value="${esc(answer)}" autocomplete="off" placeholder="Напиши свой ответ" aria-label="Ответ на вопрос ${index+1}" required>`;
}
function attachments(c,l){return `<div class="attachment-list"><button class="file-button" data-action="read-notes" data-course="${esc(c.id)}" data-lesson="${esc(l.id)}">${icon('file',22)}<span>Конспект урока<small>Читать в браузере</small></span></button><button class="file-button" data-action="slides" data-course="${esc(c.id)}" data-lesson="${esc(l.id)}">${icon('slides',22)}<span>Презентация<small>Кратко о главном</small></span></button>${(l.attachments||[]).map(f=>`<button class="file-button" data-action="view-file" data-id="${esc(f.id)}" data-name="${esc(f.name)}">${icon(f.kind==='presentation'?'slides':'file',22)}<span>${esc(f.name)}<small>${f.kind==='presentation'?'Презентация':'Методическое пособие'} · PDF</small></span></button>`).join('')}</div>`;}
function lessonPage(courseId,lessonId){const c=getCourse(courseId);if(!c||!c.published)return notFound();const lessons=allLessons(c),l=lessons.find(x=>x.id===lessonId)||lessons[0];if(!l)return coursePage(courseId);const n=lessons.indexOf(l),complete=data.progress[c.id]?.includes(l.id);return shell(`${crumbs([['Курсы','#/catalog/courses'],[c.title,`#/course/${slugPath(c.id)}`],[l.title]])}<div class="lesson-layout"><aside class="panel lesson-sidebar"><h3>${esc(c.title)}</h3>${c.modules.map(m=>`<h4>${esc(m.title)}</h4>${m.lessons.map(item=>`<a class="lesson-row ${l.id===item.id?'active':''}" href="#/lesson/${slugPath(c.id)}/${slugPath(item.id)}"><span class="number ${data.progress[c.id]?.includes(item.id)?'done':''}">${data.progress[c.id]?.includes(item.id)?icon('check',12):lessons.indexOf(item)+1}</span><span>${esc(item.title)}</span></a>`).join('')}`).join('')}</aside><article class="panel lesson-content"><div class="row"><span class="tag">Урок ${n+1} из ${lessons.length}</span>${complete?`<span class="completed-badge">${icon('check',14).replace('<svg','<svg style="display:inline;vertical-align:middle"')}Урок пройден</span>`:''}</div><h1>${esc(l.title)}</h1><div class="prose">${prose(l.theory)}</div>${attachments(c,l)}${l.questions.length?`<section class="practice"><h2>Проверим, что получилось</h2><p class="muted small">Можно пробовать снова — ошибки помогают разобраться.</p><form id="lesson-quiz" data-course="${esc(c.id)}" data-lesson="${esc(l.id)}">${l.questions.map((q,i)=>`<div class="question"><h4>${i+1}. ${esc(q.text)}</h4>${questionInput(q,i)}<div id="feedback-${i}" aria-live="polite"></div></div>`).join('')}<div class="lesson-actions"><button class="btn" type="submit">Проверить ответы ${icon('check',16)}</button><span id="lesson-score" class="small muted" role="status"></span></div></form></section>`:''}<div class="lesson-actions"><a class="text-button small" href="#/course/${slugPath(c.id)}">← К программе курса</a><button class="btn ${complete?'secondary':''}" data-action="complete-lesson" data-course="${esc(c.id)}" data-lesson="${esc(l.id)}" ${l.questions.length&&!complete?'disabled':''}>${n<lessons.length-1?'Следующий урок':'Завершить курс'} ${icon('arrow',16)}</button></div><p class="muted small" style="margin-top:12px">${l.questions.length?'Для завершения урока ответь правильно на все вопросы.':'Прочитай теорию и переходи к следующему шагу.'}</p></article></div>`,'courses');}
function materialsPage(courseId,lessonId){const c=getCourse(courseId);if(!c||!c.published)return notFound();const l=allLessons(c).find(x=>x.id===lessonId);return shell(`${crumbs([['Материалы','#/catalog/materials'],[c.title]])}<div class="page-heading"><div class="eyebrow">Учебные материалы</div><h1>${esc(c.title)}</h1><p>Выбери тему и открой нужный урок. Конспекты, методические пособия и презентации доступны для просмотра в браузере.</p></div>${l?`<div class="panel margin-bottom"><div class="row"><h2 style="margin:0">${esc(l.title)}</h2><a class="text-button small end" href="#/materials/${slugPath(c.id)}">Все уроки</a></div>${attachments(c,l)}<div class="prose" style="margin-top:26px">${prose(l.theory)}</div></div>`:c.modules.map((m,i)=>`<section class="material-group"><h3>${i+1}. ${esc(m.title)}</h3>${m.lessons.map(l=>`<div class="material-lesson"><strong>${esc(l.title)}</strong>${attachments(c,l)}<a class="text-button small" href="#/materials/${slugPath(c.id)}/${slugPath(l.id)}">Открыть урок ${icon('arrow',14)}</a></div>`).join('')}${!m.lessons.length?'<p class="muted small">В этой теме пока нет уроков.</p>':''}</section>`).join('')}<div style="margin-bottom:35px">${notice('Просмотр без кнопок скачивания. Технически любой материал, открытый в браузере, можно сохранить; абсолютная защита от копирования невозможна.')}</div>`,'materials');}
function trainerContent(school='',subject=''){
 const courses=data.courses.filter(c=>c.published&&(!school||courseInSchool(c,school))&&(!subject||c.subject===subject));
 const modules=courses.flatMap(c=>c.modules.filter(m=>m.lessons.some(l=>l.questions.length)).map(m=>({c,m})));
 return `<div class="trainer-layout"><div>${!subject?`<div class="filters"><select id="trainer-school" aria-label="Классы"><option value="">Все классы</option>${schoolPlanets.map(s=>`<option value="${s.id}" ${school===s.id?'selected':''}>${s.name} · ${s.id==='ege'?'ЕГЭ':s.grades+' классы'}</option>`).join('')}</select><select id="trainer-subject" aria-label="Направление"><option value="">Все направления</option>${data.subjects.map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')}</select></div>`:''}<div id="trainer-topics"><div class="topic-list">${modules.map(({c,m})=>`<button class="topic" data-action="start-quiz" data-course="${esc(c.id)}" data-module="${esc(m.id)}"><span class="topic-icon">${icon(c.icon,23)}</span><span><h3>${esc(m.title)}</h3><p>${esc(c.title)}</p><p>${trainingQuestions(m).length} ${plural(trainingQuestions(m).length,'вопрос','вопроса','вопросов')} · Без ограничения времени</p></span></button>`).join('')}</div>${!modules.length?empty('Здесь пока тихо','В этом направлении ещё нет заданий для выбранных классов.'):''}</div></div><aside class="panel"><span class="strip-icon" style="margin-bottom:18px">${icon('target',22)}</span><h3>Маленькая проверка,<br>большая уверенность</h3><p class="muted small">Выбери любую тему — проходить весь курс не обязательно. В конце покажем результат и разберём каждый ответ.</p><div class="progress" style="margin:22px 0"></div><p class="small muted">${icon('heart',14).replace('<svg','<svg style="display:inline;vertical-align:middle"')} Ошибаться здесь можно.</p></aside></div>`;
}
function trainerPage(){return shell(`${crumbs([['Тренажёр']])}<div class="page-heading"><div class="eyebrow">Практика без страха ошибок</div><h1>Что проверим сегодня?</h1><p>Выбирай тему, отвечай на вопросы и узнавай, что уже получается, а к чему стоит вернуться.</p></div>${trainerContent()}`,'trainer');}
function quizPage(){if(!quiz){location.hash='#/trainer';return '';}const q=quiz.questions[quiz.index];if(!q)return quizResult();return shell(`${crumbs([['Тренажёр','#/trainer'],[quiz.title]])}<div class="narrow" style="margin-bottom:45px"><div class="quiz-header"><div><div class="eyebrow">Проверяем знания</div><h1 style="margin-top:10px">${esc(quiz.title)}</h1></div><button class="text-button small" data-action="leave-quiz">Завершить позже ${icon('close',15)}</button></div><div class="row small muted"><span>Вопрос ${quiz.index+1} из ${quiz.questions.length}</span><span class="end">Не торопись. У тебя всё получится.</span></div><div class="progress"><span style="width:${(quiz.index+1)/quiz.questions.length*100}%"></span></div><form id="trainer-quiz" class="panel quiz-question" style="margin-top:25px"><span class="tag">${q.type==='choice'?'Выбери один ответ':'Введи свой ответ'}</span><h2>${esc(q.text)}</h2>${q.context?`<div class="prose"><pre><code>${esc(q.context)}</code></pre></div>`:''}${questionInput(q,0,quiz.answers[quiz.index]||'','answer')}<div class="quiz-nav"><button class="btn secondary" type="button" data-action="quiz-back" ${quiz.index===0?'disabled':''}>← Назад</button><button class="btn" type="submit">${quiz.index===quiz.questions.length-1?'Посмотреть результат':'Следующий вопрос'} ${icon('arrow',16)}</button></div></form></div>`,'trainer');}
function quizResult(){if(!quiz?.result)return trainerPage();const {right,total,feedback}=quiz.result,percent=Math.round(right/total*100);return shell(`${crumbs([['Тренажёр','#/trainer'],['Результат']])}<div class="narrow" style="margin-bottom:45px"><section class="result-header">${icon(percent>=80?'trophy':'sparkles',65)}<div class="result-score">${percent}%</div><h1 style="font-size:32px">${percent===100?'Отличное открытие!':percent>=60?'Ты на верном пути!':'Хорошее начало пути'}</h1><p>${right} из ${quiz.questions.length} ${plural(quiz.questions.length,'ответа','ответов','ответов')} верно · ${esc(quiz.title)}<br>${percent===100?'Тема усвоена отлично. Можно двигаться дальше.':percent>=60?'Основы уже получаются. Разбор поможет закрыть пробелы.':'Посмотри объяснения и повтори теорию. Следующий раз будет увереннее.'}</p><div class="row" style="justify-content:center"><button class="btn" data-action="retry-quiz">Попробовать ещё раз ${icon('arrow',15)}</button><a class="btn secondary" href="#/course/${slugPath(quiz.courseId)}">Повторить теорию</a></div></section><h2 style="font-size:24px;margin-bottom:20px">Разберём каждый ответ</h2>${quiz.questions.map((q,i)=>{const {correct,answer,explanation}=feedback[i];return `<article class="result-item"><h3><span class="${correct?'correct':'incorrect'}">${correct?'✓':'×'}</span> ${i+1}. ${esc(q.text)}</h3><p class="${correct?'correct':'incorrect'}">Твой ответ: ${esc(quiz.answers[i]||'Без ответа')}</p>${!correct?`<p>Правильный ответ: <strong>${esc(answer)}</strong></p>`:''}<p class="muted">${esc(explanation)}</p></article>`}).join('')}<a class="text-button" href="#/trainer">← Выбрать другую тему</a></div>`,'trainer');}
function profilePage(){const started=data.courses.filter(c=>c.published&&progress(c)>0),completed=started.reduce((n,c)=>n+progress(c),0);return shell(`${crumbs([['Моё обучение']])}<div class="page-heading"><div class="eyebrow">Твой личный маршрут</div><h1>С возвращением, исследователь!</h1><p>Каждый маленький шаг считается. Продолжай там, где остановился, или открывай новое.</p></div>${studyProfile()}<div class="profile-stats"><div class="stat-card purple"><strong>${completed}</strong><span>Уроков пройдено</span></div><div class="stat-card green"><strong>${(data.attemptCount??data.attempts.length)}</strong><span>Тренировок завершено</span></div><div class="stat-card peach"><strong>${started.length}</strong><span>Курсов начато</span></div></div><h2 style="font-size:25px;margin-bottom:20px">Продолжить открытия</h2>${started.length?`<div class="course-grid">${started.map(c=>courseCard(c)).join('')}</div>`:empty('Твой первый шаг впереди','Выбери курс и пройди первый урок — здесь появится твой прогресс.','Найти интересный курс','#/catalog/courses')}<section class="section"><h2 style="font-size:25px;margin-bottom:20px">Последние тренировки</h2>${data.attempts.length?data.attempts.slice(-6).reverse().map(a=>`<div class="admin-row" style="background:white;border-radius:14px;margin-bottom:10px">${icon('target',22)}<div><strong>${esc(a.title)}</strong><small>${new Date(a.date).toLocaleDateString('ru-RU')} · ${a.right} из ${a.total} верно</small></div><span class="status end">${Math.round(a.right/a.total*100)}%</span></div>`).join(''):'<p class="muted">Пока нет тренировок. <a class="text-button" href="#/trainer">Проверим знания?</a></p>'}</section>`);}
function aboutPage(){return shell(`${crumbs([['О платформе']])}<div class="page-heading"><div class="eyebrow">Образование без границ</div><h1>Любопытство — твоя суперсила</h1><p>${esc(data.platform)} — рабочее название платформы бесплатного образования. Мы создаём место, где школьники могут учиться, пробовать и находить свои интересы.</p></div><div class="about-grid">${[['book','Читай и разбирайся','Учебные материалы собраны по направлениям, большим темам и урокам. Конспекты и презентации открываются прямо в браузере.'],['play','Учись шаг за шагом','В курсах теория чередуется с практикой. Выбирай ответ или вводи его сам — и получай понятное объяснение.'],['target','Проверяй себя','Тренажёр помогает повторить отдельную тему. После теста ты увидишь результат и подробный разбор ответов.']].map(([i,t,p])=>`<div class="panel">${icon(i,40)}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div><section class="faq"><h2 style="font-size:26px;margin:35px 0 20px">Всё, что хочется спросить</h2><details open><summary>Это действительно бесплатно?</summary><p>В текущей версии все уроки, материалы и тренажёры открыты бесплатно. Подписок и платных разделов нет.</p></details><details><summary>С чего начать?</summary><p>Выбери свою школу, затем направление. Для последовательного обучения открой «Курсы», для повторения отдельной темы — «Тренажёр», для чтения — «Учебные материалы».</p></details><details><summary>Можно ли вернуться к пройденному уроку?</summary><p>Да. После входа прогресс доступен на других устройствах. Если учишься без входа, он сохраняется в этом браузере.</p></details><details><summary>Как преподавателю добавить свой курс?</summary><p>Открой редактор преподавателя внизу страницы. Добавь направление, выбери цвет карточки, создай курс, темы, уроки и задания. Можно прикрепить PDF-пособия и PDF-презентации. Редактор доступен после входа преподавателя. Сохранённые курсы появляются в общей библиотеке.</p></details></section><section class="about-banner">${icon('rocket',60)}<div><h3>Начать можно прямо сейчас</h3><p>Один урок — уже маленькое открытие.</p></div><a class="btn" href="#/schools">Выбрать школу ${icon('arrow',16)}</a></section>`,'about');}
function notFound(){return shell(`<div style="padding:65px 0">${empty('Эта орбита пока не открыта','Возможно, курс ещё не опубликован или адрес изменился.','На главную','#/')}</div>`);}

function render(){
 closeModal(false);const [page,a,b,c]=route();
 if((page==='school'||page==='subject')&&planetSchool(a)){activeSchoolId=a;sessionStorage.setItem('orbita-active-school',a);}
 const currentCourse=['course','lesson','materials'].includes(page)?getCourse(a):['quiz','result'].includes(page)&&quiz?getCourse(quiz.courseId):null;
 if(currentCourse){activeSchoolId=currentCourse.level==='Подготовка к ЕГЭ'?'ege':currentCourse.schools.includes(activeSchoolId)?activeSchoolId:currentCourse.schools[0];sessionStorage.setItem('orbita-active-school',activeSchoolId);}
 let planet=['school','subject'].includes(page)?planetSchool(a):currentCourse?(currentCourse.level==='Подготовка к ЕГЭ'?planetSchool('ege'):planetSchool(activeSchoolId)||planetSchool('senior')):['quiz','result'].includes(page)?planetSchool(activeSchoolId):null;
 document.documentElement.dataset.planet=planet?.planet||'cosmos';
 document.documentElement.classList.toggle('home-universe',!page);
 document.documentElement.classList.toggle('school-universe',page==='school'&&!!planet);
 document.documentElement.classList.toggle('learning-orbit',!!planet&&['school','subject','course','materials'].includes(page));
 document.documentElement.classList.toggle('motion-off',localStorage.getItem('orbita-motion')==='off');
 const pages={schools:schoolsPage,school:()=>schoolPage(a),subject:()=>subjectPage(a,b,c),catalog:()=>catalog(a,b),course:()=>coursePage(a),lesson:()=>lessonPage(a,b),materials:()=>materialsPage(a,b),trainer:trainerPage,quiz:quizPage,result:quizResult,profile:profilePage,about:aboutPage,admin:()=>adminPage(a,b)};
 app.innerHTML=page?(pages[page]?.()||notFound()):home();
 document.title=`${page==='admin'?'Редактор · ':''}${data.platform} — учиться интересно`;
 syncMotionButton();
 if(page==='admin'&&a==='teachers'&&isOwner())loadTeacherList().catch(e=>toast(e.message));
}
let pendingEditorNavigation=null;
document.addEventListener('click',e=>{
 const link=e.target.closest('a[href]');if(!link)return;
 if(link.classList.contains('skip-link')){e.preventDefault();document.querySelector('#main')?.focus();document.querySelector('#main')?.scrollIntoView();return;}
 if(route()[0]!=='admin'||route()[1]!=='edit'||!draft||!link.getAttribute('href').startsWith('#/')||link.getAttribute('href')===location.hash)return;
 captureCourse();if(JSON.stringify(draft)===JSON.stringify(getCourse(draft.id)))return;
 e.preventDefault();pendingEditorNavigation=link.getAttribute('href');
 showModal(`${modalHeader('Сохранить изменения курса?')}<p class="muted">В редакторе есть несохранённые изменения. Сохрани их перед переходом или вернись к редактированию.</p><div class="modal-footer"><button class="btn secondary" data-action="close-modal">Продолжить редактирование</button><button class="btn secondary" data-action="discard-course-navigation">Выйти без сохранения</button><button class="btn" data-action="save-course-navigation">Сохранить и выйти</button></div>`);
},true);
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('#main')?.focus({preventScroll:true});});

// Accessible dialogs: focus remains inside, Escape closes, focus returns to the opener.
function showModal(html,{wide=false}={}){lastFocus=document.activeElement;overlay.innerHTML=`<div class="backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1">${html}</section></div>`;document.body.style.overflow='hidden';app.inert=true;queueMicrotask(()=>overlay.querySelector('input:not([type=hidden]),select,textarea,button,a')?.focus());}
function closeModal(restore=true){if(viewer?.url)URL.revokeObjectURL(viewer.url);viewer=null;overlay.innerHTML='';document.body.style.overflow='';app.inert=false;if(restore)lastFocus?.focus?.();}
function modalHeader(title){return `<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Закрыть окно">${icon('close',17)}</button></div>`;}
document.addEventListener('keydown',e=>{if(!overlay.innerHTML)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const focusable=[...overlay.querySelectorAll('button:not([disabled]),a,input:not([disabled]),select,textarea,[tabindex="0"]')].filter(el=>el.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
overlay.addEventListener('click',e=>{if(e.target.classList.contains('backdrop'))closeModal();});
function openSearch(){showModal(`${modalHeader('Что хочется узнать?')}<div class="search-field">${icon('search',18)}<input id="search-global" placeholder="Курс, направление или тема урока" aria-label="Поиск по платформе"></div><div id="search-results" class="search-results"><p class="muted small">Например: Python, циклы или математика</p></div>`);}
function searchGlobal(query){const target=document.querySelector('#search-results');if(!target)return;const v=normalize(query);if(!v){target.innerHTML='<p class="muted small">Например: Python, циклы или математика</p>';return;}const results=[];data.subjects.filter(s=>normalize(s.title+' '+s.desc).includes(v)).forEach(s=>results.push({title:s.title,meta:'Направление · 10–11 классы',href:hrefSubject('senior',s.id),icon:s.icon}));data.courses.filter(c=>c.published).forEach(c=>{if(normalize(c.title+' '+c.desc).includes(v))results.push({title:c.title,meta:'Курс',href:`#/course/${slugPath(c.id)}`,icon:c.icon});allLessons(c).filter(l=>normalize(l.title+' '+l.theory).includes(v)).forEach(l=>results.push({title:l.title,meta:`Урок · ${c.title}`,href:`#/lesson/${slugPath(c.id)}/${slugPath(l.id)}`,icon:'book'}));});target.innerHTML=results.length?results.slice(0,20).map(r=>`<a class="search-result" href="${r.href}">${icon(r.icon,23)}<span>${esc(r.title)}<small>${esc(r.meta)}</small></span>${icon('arrow',15)}</a>`).join(''):empty('Ничего не нашлось','Попробуй другое слово.');}

function openNotes(courseId,lessonId){const c=getCourse(courseId),l=allLessons(c).find(x=>x.id===lessonId);if(!l)return;showModal(`${modalHeader(l.title)}<span class="tag">Конспект · ${esc(c.title)}</span><div class="prose" style="margin-top:24px">${prose(l.theory)}</div><p class="small muted">Материал для просмотра в браузере.</p>`,{wide:true});}
function openSlides(courseId,lessonId){const c=getCourse(courseId),l=allLessons(c).find(x=>x.id===lessonId);if(!l)return;const paragraphs=l.theory.split(/\n\s*\n/).filter(Boolean);viewer={type:'slides',title:l.title,slides:paragraphs,theme:safeTheme(c.theme),icon:c.icon,index:0};showModal(`${modalHeader(`Презентация: ${l.title}`)}<div id="slide-container"></div><div class="viewer-toolbar" style="margin:20px 0 0"><button class="btn secondary small" data-action="slide-prev">← Назад</button><span id="slide-count" class="small muted"></span><button class="btn small" data-action="slide-next">Далее ${icon('arrow',14)}</button></div>`,{wide:true});paintSlide();}
function paintSlide(){if(!viewer)return;const v=viewer;document.querySelector('#slide-container').innerHTML=`<div class="slide ${v.theme}">${icon(v.icon,65)}<h2>${esc(v.title)}</h2>${v.slides[v.index].startsWith('```')?`<pre>${esc(v.slides[v.index].replace(/```[\w]*\n?/g,''))}</pre>`:`<p>${esc(v.slides[v.index])}</p>`}<small>${v.index+1} / ${v.slides.length}</small></div>`;document.querySelector('#slide-count').textContent=`Слайд ${v.index+1} из ${v.slides.length}`;overlay.querySelector('[data-action="slide-prev"]').disabled=v.index===0;overlay.querySelector('[data-action="slide-next"]').disabled=v.index===v.slides.length-1;}
async function openPdf(id,name){showModal(`${modalHeader(name)}<div class="viewer-toolbar"><button class="btn secondary small" data-action="pdf-prev">← Назад</button><span id="pdf-count" class="small muted">Открываем материал…</span><button class="btn secondary small" data-action="pdf-next">Далее ${icon('arrow',14)}</button></div><div id="pdf-stage" class="pdf-stage"><p class="muted small">Загрузка PDF…</p></div>`,{wide:true});try{const file=await fetchPdf(id);if(!file)throw new Error('Файл не найден в этом браузере. Попросите преподавателя загрузить его заново.');const pdfjs=await import('./vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;if(!overlay.innerHTML)return;viewer={type:'pdf',pdf,index:1,rendering:false};await paintPdf();}catch(err){const stage=document.querySelector('#pdf-stage');if(stage)stage.textContent=`Не удалось открыть материал. ${err.message}`;}}
async function paintPdf(){if(!viewer||viewer.rendering)return;const v=viewer;v.rendering=true;try{const page=await v.pdf.getPage(v.index);if(viewer!==v)return;const viewport=page.getViewport({scale:1.6}),canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;canvas.setAttribute('role','img');canvas.setAttribute('aria-label',`Страница ${v.index} PDF-документа`);const stage=document.querySelector('#pdf-stage');if(!stage)return;stage.replaceChildren(canvas);await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;const text=await page.getTextContent();canvas.setAttribute('aria-label',`Страница ${v.index}. ${text.items.map(x=>x.str).join(' ')}`);if(viewer!==v)return;document.querySelector('#pdf-count').textContent=`Страница ${v.index} из ${v.pdf.numPages}`;overlay.querySelector('[data-action="pdf-prev"]').disabled=v.index===1;overlay.querySelector('[data-action="pdf-next"]').disabled=v.index===v.pdf.numPages;}finally{v.rendering=false;}}

// Teacher editor. All library mutations are authorized and stored by the server.
function teacherLoginPage(){
 const denied=session.role==='student';
 return shell(`${crumbs([['Преподавателям']])}<div class="narrow" style="padding:35px 0 65px"><section class="panel" style="text-align:center;padding:45px"><span class="strip-icon" style="margin:0 auto 24px">${icon('lock',24)}</span><div class="eyebrow" style="justify-content:center">Мастерская знаний</div><h1 style="font-size:35px;margin:15px 0">${denied?'Доступ только для преподавателей':'Вход для преподавателей'}</h1><p class="muted" style="max-width:530px;margin:0 auto 25px">${denied?'Этот аккаунт не добавлен в список преподавателей. Попросите владельца платформы предоставить вам доступ.':'Войдите через свой аккаунт ChatGPT. Редактор доступен только преподавателям, которым владелец предоставил права.'}</p>${session.user?`<p class="small muted margin-bottom">${esc(session.user.email)}</p>`:''}<div class="row" style="justify-content:center">${denied?`<a class="btn secondary" href="${esc(session.signOut)}" target="_top">Выйти из аккаунта</a>`:`<a class="btn" href="${esc(session.signIn)}" target="_top">${icon('user',17)}Войти через ChatGPT</a>`}<a class="btn secondary" href="#/">Вернуться к обучению ${icon('arrow',16)}</a></div></section></div>`);
}
function teachersPanel(){return `<div class="admin-toolbar"><h2>Преподаватели</h2><span class="tag">Только для владельца</span></div><section class="panel margin-bottom"><h3>Предоставить доступ</h3><p class="muted small margin-bottom">Укажи email аккаунта ChatGPT преподавателя. После входа с этим аккаунтом человек сможет редактировать курсы. Доступ к самому приватному сайту предоставляется отдельно.</p><form id="teacher-form"><div class="row"><input type="email" name="email" aria-label="Email преподавателя" placeholder="teacher@example.com" maxlength="254" required style="flex:1"><button class="btn small" type="submit">${icon('plus',15)}Добавить преподавателя</button></div></form></section><div class="admin-table"><div class="admin-row">${icon('lock',20)}<div><strong>${esc(session.user?.email)}</strong><small>Владелец платформы · постоянный доступ</small></div></div><div id="teacher-list"><div class="admin-row muted small">Загружаем список…</div></div></div>`;}
async function loadTeacherList(){const result=await api('admin/teachers'),target=document.querySelector('#teacher-list');if(!target)return;target.innerHTML=result.teachers.length?result.teachers.map(t=>`<div class="admin-row">${icon('user',20)}<div><strong>${esc(t.email)}</strong><small>Преподаватель</small></div><div class="actions"><button class="btn danger small" data-action="remove-teacher" data-email="${esc(t.email)}">Отключить доступ</button></div></div>`).join(''):'<div class="admin-row muted small">Другие преподаватели ещё не добавлены.</div>';}
function legacyPanel(){return isOwner()&&localStorage.getItem('orbita-before-server-v1')?`<section class="panel" style="margin-top:22px"><h3>Материалы из прежней версии</h3><p class="muted small margin-bottom">В этом браузере сохранена копия библиотеки прежней версии сайта. Её можно перенести вместе с доступными PDF. Перенос заменит общую библиотеку, поэтому сначала сохрани её резервную копию.</p><button class="btn secondary small" data-action="migrate-legacy">Перенести прежнюю библиотеку</button></section>`:'';}
async function migrateLegacy(){
 if(!isOwner())return;
 librarySaving=true;
 try{
  const previous=JSON.parse(localStorage.getItem('orbita-before-server-v1'));validateImport(previous);
  for(const c of previous.courses)for(const l of allLessons(c))for(let i=0;i<l.attachments.length;i++){
   const old=l.attachments[i];const file=await getFile(old.id);if(!file)throw new Error(`В прежнем браузерном хранилище отсутствует ${old.name}. Экспортируйте старую библиотеку, уберите недоступное вложение и импортируйте JSON.`);
   l.attachments[i]=await uploadPdf(new File([file],old.name,{type:'application/pdf'}),old.kind);
  }
  const next={...data,platform:previous.platform,subjects:previous.subjects,courses:previous.courses};
  await saveLibrary(next);Object.assign(data,next);persist();localStorage.removeItem('orbita-before-server-v1');closeModal();render();toast('Прежняя библиотека и PDF перенесены на сервер.');
 }catch(e){toast(e.message);}finally{librarySaving=false;}
}
function adminPage(tab='courses',id){
 if(!canEdit())return teacherLoginPage();
 if(tab==='edit')return courseEditor(id);
 const menu=[...(isOwner()?[['teachers','Преподаватели','user']]:[]),['courses','Курсы и уроки','book'],['subjects','Направления','grid'],['materials','Материалы','file'],['settings','Настройки','settings']];
 const side=`<aside class="admin-menu">${menu.map(([key,title,i])=>`<a href="#/admin/${key}" class="${tab===key?'active':''}">${icon(i,19)}${title}</a>`).join('')}<a href="#/" class="muted">${icon('arrow',18)}На сайт</a><a href="${esc(session.signOut)}" target="_top" class="muted">${icon('lock',18)}Выйти</a></aside>`;
 let content='';
 if(tab==='teachers'&&isOwner())content=teachersPanel();
 else if(tab==='subjects')content=`<div class="admin-toolbar"><h2>Направления</h2><button class="btn small" data-action="new-subject">${icon('plus',16)}Добавить направление</button></div><div class="admin-table">${data.subjects.map(s=>`<div class="admin-row"><span class="item-icon ${safeTheme(s.theme)}">${icon(s.icon,25)}</span><div><strong>${esc(s.title)}</strong><small>${s.schools.map(x=>schoolById(x).grades).join(' · ')} классы</small></div><div class="actions"><button class="btn secondary small" data-action="edit-subject" data-id="${esc(s.id)}">${icon('edit',14)}Изменить</button><button class="icon-button" data-action="delete-subject" data-id="${esc(s.id)}" aria-label="Удалить направление ${esc(s.title)}">${icon('trash',16)}</button></div></div>`).join('')}</div>`;
 else if(tab==='materials')content=`<div class="admin-toolbar"><h2>Материалы уроков</h2></div><p class="muted small margin-bottom">Открой курс, затем урок, чтобы прикрепить PDF-пособие или презентацию. Для PowerPoint используйте «Сохранить как → PDF».</p><div class="admin-table">${data.courses.map(c=>`<div class="admin-row"><span class="item-icon ${safeTheme(c.theme)}">${icon('file',25)}</span><div><strong>${esc(c.title)}</strong><small>${allLessons(c).reduce((n,l)=>n+(l.attachments?.length||0),0)} прикреплённых файлов · ${allLessons(c).length} уроков с конспектами</small></div><div class="actions"><a class="btn secondary small" href="#/admin/edit/${slugPath(c.id)}">Открыть уроки ${icon('arrow',14)}</a></div></div>`).join('')}</div>`;
 else if(tab==='settings')content=`<div class="admin-toolbar"><h2>Настройки платформы</h2></div><section class="panel"><form id="platform-form"><div class="form-field"><label for="platform-name">Название платформы</label><input id="platform-name" name="name" value="${esc(data.platform)}" maxlength="30" required><small>«Орбита» — рабочее название. Оно изменится в шапке и на страницах.</small></div><button class="btn small" type="submit">Сохранить название</button></form></section><section class="panel" style="margin-top:22px"><h3>Резервная копия библиотеки</h3><p class="muted small margin-bottom">Экспорт сохраняет направления, курсы, уроки, вопросы и прогресс в JSON. Прикреплённые PDF хранятся на сервере и не входят в JSON-копию. Ссылки на загруженные файлы сохраняются.</p><div class="row"><button class="btn secondary small" data-action="export">${icon('download',16)}Экспорт JSON</button><label class="btn secondary small" for="import-data">${icon('upload',16)}Импорт JSON</label><input id="import-data" type="file" accept="application/json,.json" hidden></div></section>${legacyPanel()}`;
 else content=`<div class="admin-toolbar"><h2>Курсы и уроки</h2><button class="btn small" data-action="new-course">${icon('plus',16)}Создать курс</button></div><div class="admin-table">${data.courses.map(c=>`<div class="admin-row"><span class="item-icon ${safeTheme(c.theme)}">${icon(c.icon,25)}</span><div><strong>${esc(c.title)}</strong><small>${esc(getSubject(c.subject)?.title)} · ${c.modules.length} тем · ${allLessons(c).length} уроков</small></div><div class="actions"><span class="status ${c.published?'':'draft'}">${c.published?'Опубликован':'Черновик'}</span><a class="btn secondary small" href="#/admin/edit/${slugPath(c.id)}">${icon('edit',14)}Изменить</a><button class="icon-button" data-action="delete-course" data-id="${esc(c.id)}" aria-label="Удалить курс ${esc(c.title)}">${icon('trash',16)}</button></div></div>`).join('')}</div>`;
 return shell(`${crumbs([['Преподавателям']])}<div class="page-heading"><div class="eyebrow">Мастерская знаний</div><h1>Место, где рождаются открытия</h1><p>Создавай курсы, добавляй уроки и делись тем, что любишь.</p></div>${notice(`Вы вошли как ${esc(session.user?.email)}. Изменения сохраняются в общей библиотеке сайта; черновики доступны только преподавателям.`)}<div class="admin-layout">${side}<div>${content}</div></div>`);
}
function schoolCheckboxes(selected){return `<div class="checkboxes">${schools.map(s=>`<label><input type="checkbox" name="schools" value="${s.id}" ${selected.includes(s.id)?'checked':''}>${s.grades} классы</label>`).join('')}</div>`;}
function themeRadios(current){return `<div class="theme-options">${Object.entries(themes).map(([key,title])=>`<label class="theme-option ${key}"><input type="radio" name="theme" value="${key}" ${current===key?'checked':''}>${title}</label>`).join('')}</div>`;}
function openSubject(id){const s=id?getSubject(id):{id:uid(),title:'',desc:'',theme:'purple',icon:'globe',schools:schools.map(s=>s.id)};showModal(`${modalHeader(id?'Редактировать направление':'Новое направление')}<form id="subject-form" data-id="${esc(s.id)}"><div class="form-field"><label for="subject-title">Название</label><input id="subject-title" name="title" value="${esc(s.title)}" placeholder="Например, китайский язык" maxlength="80" required></div><div class="form-field"><label for="subject-desc">Текст на обратной стороне карточки</label><textarea id="subject-desc" name="desc" maxlength="250" required>${esc(s.desc)}</textarea></div><div class="form-field"><span>Школы</span>${schoolCheckboxes(s.schools)}</div><div class="form-field"><span>Настроение карточки</span>${themeRadios(safeTheme(s.theme))}</div><div class="form-field"><label for="subject-icon">Иллюстрация</label><select id="subject-icon" name="icon">${[['globe','Планета и языки'],['code','Код'],['math','Математика'],['robot','Робот'],['letters','Буквы'],['atom','Атом'],['star','Звезда'],['rocket','Ракета'],['book','Книга']].map(([key,title])=>`<option value="${key}" ${s.icon===key?'selected':''}>${title}</option>`).join('')}</select></div><div class="modal-footer"><button class="btn secondary" type="button" data-action="close-modal">Отмена</button><button class="btn" type="submit">Сохранить направление ${icon('check',16)}</button></div></form>`);}
function courseEditor(id){if(!canEdit())return teacherLoginPage();const c=getCourse(id);if(!c)return notFound();draft=structuredClone(c);return courseEditorShell();}
function courseEditorShell(){return shell(`${crumbs([['Редактор','#/admin/courses'],[draft.title]])}<div class="page-heading"><div class="eyebrow">Редактор курса</div><h1>${esc(draft.title||'Новый курс')}</h1><p>Сначала настрой карточку, затем собери маршрут из тем и уроков.</p></div>${notice('Сохраняй курс после изменения его настроек или структуры. Кнопка «Сохранить урок» обновляет урок в черновике курса.')}<form id="course-form"><div class="row margin-bottom"><a class="text-button small" href="#/admin/courses">← Все курсы</a><button class="btn end" type="submit">Сохранить курс ${icon('check',16)}</button></div><section class="panel margin-bottom"><h2>Карточка курса</h2><div class="form-grid"><div class="form-field"><label for="course-title">Название курса</label><input id="course-title" name="title" value="${esc(draft.title)}" maxlength="100" required></div><div class="form-field"><label for="course-subject">Направление</label><select id="course-subject" name="subject" required>${data.subjects.map(s=>`<option value="${esc(s.id)}" ${draft.subject===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></div><div class="form-field full-width"><label for="course-desc">Описание</label><textarea id="course-desc" name="desc" maxlength="400" required>${esc(draft.desc)}</textarea></div><div class="form-field"><label for="course-level">Уровень</label><select id="course-level" name="level">${['С нуля','Базовый','Продвинутый','Подготовка к ЕГЭ','Первое знакомство'].map(x=>`<option ${draft.level===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><span>Видимость</span><label class="option"><input name="published" type="checkbox" ${draft.published?'checked':''}>Опубликован в каталоге</label></div><div class="form-field full-width"><span>Школы</span>${schoolCheckboxes(draft.schools)}</div><div class="form-field full-width"><span>Дизайн курса</span>${themeRadios(safeTheme(draft.theme))}</div></div></section><section class="panel margin-bottom"><div class="admin-toolbar"><h2 style="margin:0">Темы и уроки</h2><button class="btn secondary small" type="button" data-action="add-module">${icon('plus',15)}Добавить тему</button></div><div id="edit-modules">${editModules()}</div></section><div class="row" style="margin-bottom:40px"><a class="btn secondary" href="#/admin/courses">Закрыть редактор</a><button class="btn end" type="submit">Сохранить курс ${icon('check',16)}</button></div></form>`);}
function editModules(){return draft.modules.length?draft.modules.map((m,i)=>`<section class="edit-module"><div class="edit-module-head"><span class="tag">${i+1}</span><input name="module-${esc(m.id)}" value="${esc(m.title)}" aria-label="Название темы ${i+1}" required><button class="icon-button" type="button" data-action="remove-module" data-id="${esc(m.id)}" aria-label="Удалить тему ${esc(m.title)}">${icon('trash',15)}</button></div>${m.lessons.map(l=>`<div class="edit-lesson">${icon('book',17)}<span>${esc(l.title)} <small class="muted">· ${l.questions.length} заданий · ${l.attachments?.length||0} PDF</small></span><button class="btn secondary small" type="button" data-action="edit-lesson" data-module="${esc(m.id)}" data-id="${esc(l.id)}">Изменить</button><button class="icon-button" type="button" data-action="remove-lesson" data-module="${esc(m.id)}" data-id="${esc(l.id)}" aria-label="Удалить урок ${esc(l.title)}">${icon('trash',15)}</button></div>`).join('')}<button class="text-button small" type="button" data-action="add-lesson" data-module="${esc(m.id)}">${icon('plus',15)}Добавить урок</button></section>`).join(''):empty('Добавь первую тему','Внутри темы можно создать уроки с теорией, заданиями и файлами.');}
function captureCourse(){const f=document.querySelector('#course-form');if(!f)return;const values=new FormData(f);Object.assign(draft,{title:String(values.get('title')||'').trim(),desc:String(values.get('desc')||'').trim(),subject:String(values.get('subject')||''),level:String(values.get('level')||'С нуля'),theme:safeTheme(values.get('theme')),schools:values.getAll('schools'),published:values.has('published')});draft.icon=getSubject(draft.subject)?.icon||'book';draft.modules.forEach(m=>m.title=String(values.get(`module-${m.id}`)||m.title).trim());}
function refreshModules(){document.querySelector('#edit-modules').innerHTML=editModules();}
function openLesson(moduleId,id){captureCourse();const m=draft.modules.find(x=>x.id===moduleId);lessonDraft={moduleId,lesson:structuredClone(id?m.lessons.find(l=>l.id===id):{id:uid(),title:'',theory:'',questions:[],attachments:[]}),pendingFiles:[],removedFiles:[]};paintLessonEditor();}
function captureLesson(){const form=document.querySelector('#lesson-form');if(!form)return;const f=new FormData(form),l=lessonDraft.lesson;l.title=String(f.get('title')||'').trim();l.theory=String(f.get('theory')||'').trim();l.questions.forEach((q,i)=>{q.text=String(f.get(`text-${i}`)||'').trim();q.type=String(f.get(`type-${i}`)||'choice');q.options=q.type==='choice'?String(f.get(`options-${i}`)||'').split('\n').map(x=>x.trim()).filter(Boolean):[];q.answer=String(f.get(`answer-${i}`)||'').trim();q.explanation=String(f.get(`explanation-${i}`)||'').trim();});}
function paintLessonEditor(){const l=lessonDraft.lesson;showModal(`${modalHeader(l.title||'Новый урок')}<form id="lesson-form"><div class="form-field"><label for="lesson-title">Название урока</label><input name="title" id="lesson-title" value="${esc(l.title)}" maxlength="150" required></div><div class="form-field"><label for="lesson-theory">Теория</label><textarea class="theory" name="theory" id="lesson-theory" required>${esc(l.theory)}</textarea><small>Разделяйте абзацы пустой строкой. Код можно обернуть в тройные обратные кавычки: &#96;&#96;&#96;python … &#96;&#96;&#96;. Конспект и презентация создаются из теории автоматически.</small></div><h3>Материалы урока</h3><p class="muted small">Методические пособия и презентации — в формате PDF. Файлы PowerPoint предварительно экспортируйте в PDF. Лимит одного файла: 20 МБ.</p><div class="file-list-edit">${(l.attachments||[]).map(f=>`<div>${icon('file',17)}<span>${esc(f.name)}</span><button class="icon-button" type="button" data-action="remove-attachment" data-id="${esc(f.id)}" aria-label="Удалить файл ${esc(f.name)}">${icon('trash',14)}</button></div>`).join('')}${lessonDraft.pendingFiles.map((f,i)=>`<div>${icon('file',17)}<span>${esc(f.file.name)} <small class="muted">· новый</small></span><button class="icon-button" type="button" data-action="remove-pending-file" data-index="${i}" aria-label="Убрать файл">${icon('close',14)}</button></div>`).join('')}</div><div class="form-grid"><label class="upload-label">Методическое пособие<input type="file" id="upload-notes" accept="application/pdf,.pdf" multiple></label><label class="upload-label">Презентация в PDF<input type="file" id="upload-presentation" accept="application/pdf,.pdf" multiple></label></div><div class="admin-toolbar" style="margin-top:28px"><h3>Задания</h3><button class="btn secondary small" type="button" data-action="add-question">${icon('plus',14)}Добавить задание</button></div><div id="edit-questions">${l.questions.map((q,i)=>editQuestion(q,i)).join('')}${!l.questions.length?'<p class="muted small">Урок может содержать только теорию. Добавь задания для практики и тренажёра.</p>':''}</div><div class="modal-footer"><button class="btn secondary" type="button" data-action="close-modal">Отмена</button><button class="btn" type="submit">Сохранить урок ${icon('check',15)}</button></div></form>`,{wide:true});}
function editQuestion(q,i){return `<section class="edit-question"><div class="edit-question-head"><strong>Задание ${i+1}</strong><button class="icon-button" type="button" data-action="remove-question" data-index="${i}" aria-label="Удалить задание ${i+1}">${icon('trash',15)}</button></div><div class="form-field"><label for="question-text-${i}">Вопрос</label><textarea name="text-${i}" id="question-text-${i}" required>${esc(q.text)}</textarea></div><div class="form-field"><label for="question-type-${i}">Тип ответа</label><select name="type-${i}" id="question-type-${i}" data-action="question-type"><option value="choice" ${q.type==='choice'?'selected':''}>Выбор одного ответа</option><option value="text" ${q.type==='text'?'selected':''}>Самостоятельный ввод</option></select></div>${q.type==='choice'?`<div class="form-field"><label for="question-options-${i}">Варианты ответа — каждый с новой строки</label><textarea name="options-${i}" id="question-options-${i}" required>${esc(q.options.join('\n'))}</textarea></div>`:''}<div class="form-field"><label for="question-answer-${i}">Правильный ответ</label><input name="answer-${i}" id="question-answer-${i}" value="${esc(q.answer)}" required><small>${q.type==='choice'?'Должен точно совпадать с одним из вариантов.':'Регистр букв и пробелы по краям не учитываются.'}</small></div><div class="form-field"><label for="question-explanation-${i}">Объяснение ответа</label><textarea name="explanation-${i}" id="question-explanation-${i}" required>${esc(q.explanation)}</textarea></div></section>`;}
function askDelete(title,description,action,id,extra=''){showModal(`${modalHeader(title)}<p class="muted">${esc(description)}</p><div class="modal-footer"><button class="btn secondary" data-action="close-modal">Отмена</button><button class="btn danger" data-action="${action}" data-id="${esc(id)}" ${extra}>Удалить</button></div>`);}
function validateCourse(c){if(!c.title||!c.desc||!c.subject)return 'Заполни название, описание и направление курса.';if(!c.schools.length)return 'Выбери хотя бы одну школу.';const sub=getSubject(c.subject);if(c.schools.some(s=>!sub.schools.includes(s)))return 'Курс доступен школе, в которой нет его направления. Сначала добавь эту школу в настройках направления.';if(c.published&&(!allLessons(c).length||c.modules.some(m=>!m.lessons.length)))return 'Для публикации добавь хотя бы один урок в каждую тему. Или сохрани курс как черновик.';return '';}
function validateLesson(l){if(!l.title||!l.theory)return 'Заполни название и теорию урока.';for(const q of l.questions){if(!q.text||!q.answer||!q.explanation)return 'Заполни вопрос, правильный ответ и объяснение каждого задания.';if(q.type==='choice'&&(q.options.length<2||new Set(q.options).size!==q.options.length||!q.options.includes(q.answer)))return 'Для выбора ответа нужно хотя бы два разных варианта. Правильный ответ должен точно совпадать с одним из них.';}return '';}

// All user-authored content is rendered as text, including theory and code.
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='scroll-schools'){e.preventDefault();document.querySelector('#planet-schools')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});return;}
 if(a==='earth-menu'){const panel=document.querySelector('#earth-navigation');const expanded=el.getAttribute('aria-expanded')!=='true';el.setAttribute('aria-expanded',String(expanded));panel.hidden=!expanded;return;}
 if(a==='toggle-motion'){const disabled=!document.documentElement.classList.contains('motion-off');document.documentElement.classList.toggle('motion-off',disabled);localStorage.setItem('orbita-motion',disabled?'off':'on');syncMotionButton();return;}
 if(adminActions.has(a)&&!canEdit()){e.preventDefault();toast('Для редактирования войдите как преподаватель.');return;}
 if(librarySaving&&adminActions.has(a)){e.preventDefault();toast('Дождитесь завершения сохранения.');return;}
 if(el.tagName==='BUTTON'&&el.disabled)return;
 if(a==='ripple'||a==='fish'){const scene=el.closest('.space')||el;const rect=scene.getBoundingClientRect();const x=e.detail?e.clientX-rect.left:el.offsetLeft+el.offsetWidth/2,y=e.detail?e.clientY-rect.top:el.offsetTop+el.offsetHeight/2;const ripple=document.createElement('div');ripple.className='ripple';ripple.style.left=x+'px';ripple.style.top=y+'px';scene.append(ripple);setTimeout(()=>ripple.remove(),1400);return;}
 if(a==='reload-library')bootstrap();
 if(a==='migrate-legacy'&&isOwner())showModal(`${modalHeader('Перенести прежнюю библиотеку?')}<p class="muted">Общая библиотека будет заменена сохранённой в этом браузере копией. PDF будут перенесены на сервер. Сначала экспортируйте текущую общую библиотеку, если в ней уже есть новые материалы.</p><div class="modal-footer"><button class="btn secondary" data-action="close-modal">Отмена</button><button class="btn" data-action="confirm-migrate-legacy">Перенести библиотеку</button></div>`);
 if(a==='confirm-migrate-legacy')await migrateLegacy();
 if(a==='search')openSearch();
 if(a==='remove-teacher'){if(!isOwner())return;showModal(`${modalHeader('Отключить доступ преподавателя?')}<p class="muted">${esc(el.dataset.email)} больше не сможет сохранять изменения, удалять курсы или загружать материалы.</p><div class="modal-footer"><button class="btn secondary" data-action="close-modal">Отмена</button><button class="btn danger" data-action="confirm-remove-teacher" data-email="${esc(el.dataset.email)}">Отключить доступ</button></div>`);}
 if(a==='confirm-remove-teacher'){try{await api('admin/teachers',{method:'DELETE',body:JSON.stringify({email:el.dataset.email})});closeModal();await loadTeacherList();toast('Доступ преподавателя отключён.');}catch(e){toast(e.message);}}
 if(a==='discard-course-navigation'){const target=pendingEditorNavigation;draft=null;closeModal();location.hash=target;}
 if(a==='save-course-navigation'){const error=validateCourse(draft);if(error){toast(error);return;}data.courses[data.courses.findIndex(c=>c.id===draft.id)]=structuredClone(draft);if(await persistLibrary()){const target=pendingEditorNavigation;draft=null;closeModal();location.hash=target;toast('Курс сохранён.');}}
 if(a==='close-modal')closeModal();
 if(a==='read-notes')openNotes(el.dataset.course,el.dataset.lesson);
 if(a==='slides')openSlides(el.dataset.course,el.dataset.lesson);
 if(a==='slide-prev'&&viewer?.index>0){viewer.index--;paintSlide();}
 if(a==='slide-next'&&viewer?.index<viewer.slides.length-1){viewer.index++;paintSlide();}
 if(a==='view-file')await openPdf(el.dataset.id,el.dataset.name);
 if(a==='pdf-prev'&&viewer?.index>1&&!viewer.rendering){viewer.index--;await paintPdf();}
 if(a==='pdf-next'&&viewer?.index<viewer.pdf.numPages&&!viewer.rendering){viewer.index++;await paintPdf();}
 if(a==='complete-lesson')await advanceLesson(el);
 if(a==='start-quiz')openTraining(el.dataset.course,el.dataset.module);
 if(a==='quiz-back'&&quiz){const f=document.querySelector('#trainer-quiz');quiz.answers[quiz.index]=new FormData(f).get('answer0')||'';quiz.index=Math.max(0,quiz.index-1);render();}
 if(a==='leave-quiz')askLeaveQuiz();
 if(a==='confirm-leave-quiz'){quiz=null;closeModal();location.hash='#/trainer';}
 if(a==='retry-quiz'&&quiz){openTraining(quiz.courseId,quiz.moduleId);}
 if(a==='new-subject')openSubject();
 if(a==='edit-subject')openSubject(el.dataset.id);
 if(a==='delete-subject'){const s=getSubject(el.dataset.id),count=data.courses.filter(c=>c.subject===s.id).length;if(count){toast('Сначала удали или перенеси курсы этого направления.');return;}askDelete('Удалить направление?',s.title,'confirm-delete-subject',s.id);}
 if(a==='confirm-delete-subject'){data.subjects=data.subjects.filter(s=>s.id!==el.dataset.id);if(!await persistLibrary())return;closeModal();render();toast('Направление удалено.');}
 if(a==='new-course'){if(!data.subjects.length){toast('Сначала добавь направление.');return;}const c={id:uid(),title:'Новый курс',desc:'',subject:data.subjects[0].id,theme:data.subjects[0].theme,icon:data.subjects[0].icon,level:'С нуля',schools:[...data.subjects[0].schools],published:false,modules:[]};data.courses.push(c);if(!await persistLibrary())return;location.hash=`#/admin/edit/${c.id}`;}
 if(a==='delete-course'){const c=getCourse(el.dataset.id);askDelete('Удалить курс?',`«${c.title}» и все его темы и уроки будут удалены из общей библиотеки.`,'confirm-delete-course',c.id);}
 if(a==='confirm-delete-course'){const c=getCourse(el.dataset.id);for(const f of allLessons(c).flatMap(l=>l.attachments||[]))await deleteFile(f.id).catch(()=>{});data.courses=data.courses.filter(c=>c.id!==el.dataset.id);delete data.progress[el.dataset.id];if(!await persistLibrary())return;closeModal();render();toast('Курс удалён.');}
 if(a==='add-module'){captureCourse();draft.modules.push({id:uid(),title:'Новая тема',lessons:[]});refreshModules();}
 if(a==='remove-module'){captureCourse();const m=draft.modules.find(m=>m.id===el.dataset.id);askDelete('Удалить тему?',`«${m.title}» и её уроки будут удалены из черновика курса.`,'confirm-remove-module',m.id);}
 if(a==='confirm-remove-module'){draft.modules=draft.modules.filter(m=>m.id!==el.dataset.id);closeModal();refreshModules();}
 if(a==='add-lesson')openLesson(el.dataset.module);
 if(a==='edit-lesson')openLesson(el.dataset.module,el.dataset.id);
 if(a==='remove-lesson'){captureCourse();const m=draft.modules.find(m=>m.id===el.dataset.module),l=m.lessons.find(l=>l.id===el.dataset.id);askDelete('Удалить урок?',`«${l.title}» будет удалён из черновика курса.`,'confirm-remove-lesson',l.id,`data-module="${esc(m.id)}"`);}
 if(a==='confirm-remove-lesson'){const m=draft.modules.find(m=>m.id===el.dataset.module);m.lessons=m.lessons.filter(l=>l.id!==el.dataset.id);closeModal();refreshModules();}
 if(a==='add-question'){captureLesson();lessonDraft.lesson.questions.push({id:uid(),text:'',type:'choice',options:['Первый вариант','Второй вариант'],answer:'',explanation:''});paintLessonEditor();}
 if(a==='remove-question'){captureLesson();lessonDraft.lesson.questions.splice(Number(el.dataset.index),1);paintLessonEditor();}
 if(a==='remove-attachment'){captureLesson();lessonDraft.removedFiles.push(el.dataset.id);lessonDraft.lesson.attachments=lessonDraft.lesson.attachments.filter(f=>f.id!==el.dataset.id);paintLessonEditor();}
 if(a==='remove-pending-file'){captureLesson();lessonDraft.pendingFiles.splice(Number(el.dataset.index),1);paintLessonEditor();}
 if(a==='export'){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='orbita-library.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Копия библиотеки сохранена. PDF хранятся отдельно на сервере.');}
 if(a==='confirm-import'){const incoming=JSON.parse(el.dataset.import);Object.assign(data,{platform:incoming.platform,subjects:incoming.subjects,courses:incoming.courses});if(!await persistLibrary())return;closeModal();render();toast('Библиотека импортирована на сервер.');}
});
function askLeaveQuiz(){showModal(`${modalHeader('Вернуться к выбору темы?')}<p class="muted">Незавершённая тренировка не попадёт в статистику. Можно начать её заново в любое время.</p><div class="modal-footer"><button class="btn secondary" data-action="close-modal">Продолжить</button><button class="btn" data-action="confirm-leave-quiz">Вернуться к темам</button></div>`);}

function studyProfile(){
 if(!session.user)return `${notice('Прогресс гостя хранится в этом браузере. После входа новые результаты будут доступны на других устройствах.')}<p class="margin-bottom"><a class="btn" href="${esc(session.studySignIn)}">Войти через ChatGPT</a></p>`;
 const status=studyProfileUnavailable?'Не удалось загрузить историю обучения.':'Прогресс сохраняется в аккаунте и доступен на других устройствах.';
 return `${notice(status)}<div class="row margin-bottom">${studyProfileUnavailable?'<button class="btn secondary" data-action="reload-library">Загрузить историю</button>':''}<a class="btn secondary" href="${esc(session.studySignOut)}">Выйти</a></div>`;
}

const submitStudy=(kind,input)=>api('learning/'+kind,{
 method:'POST',body:JSON.stringify({...input,account:session.user?.id??null}),
});
const submittedAnswers=(questions,values)=>questions.map((question,index)=>({id:question.id,value:values[index]}));

function markLessonComplete(courseId,lessonId){
 const completed=data.progress[courseId]??=[];
 if(!completed.includes(lessonId))completed.push(lessonId);
 if(!session.user)persist();
}

async function advanceLesson(button){
 if(button.disabled)return;
 const course=getCourse(button.dataset.course),lessons=allLessons(course);
 const index=lessons.findIndex(lesson=>lesson.id===button.dataset.lesson);
 if(index<0)return;
 const lesson=lessons[index];
 button.disabled=true;
 try{
  if(!data.progress[course.id]?.includes(lesson.id)){
   const result=await submitStudy('lesson',{courseId:course.id,lessonId:lesson.id,answers:[]});
   if(!result.completed)return;
   markLessonComplete(course.id,lesson.id);
  }
  if(!button.isConnected)return;
  if(index<lessons.length-1)location.hash=`#/lesson/${slugPath(course.id)}/${slugPath(lessons[index+1].id)}`;
  else{location.hash=`#/course/${slugPath(course.id)}`;toast('Курс пройден! Ещё одно большое открытие.');}
 }catch(error){toast(error.message);}
 finally{button.disabled=false;}
}

async function checkLesson(form){
 const button=form.querySelector('button[type="submit"]');
 if(button.disabled)return;
 const course=getCourse(form.dataset.course);
 const lesson=allLessons(course).find(item=>item.id===form.dataset.lesson);
 const values=new FormData(form);
 const answers=submittedAnswers(lesson.questions,lesson.questions.map((_,index)=>values.get(`q${index}`)));
 button.disabled=true;
 try{
  const result=await submitStudy('lesson',{courseId:course.id,lessonId:lesson.id,answers});
  if(result.completed)markLessonComplete(course.id,lesson.id);
  if(!form.isConnected)return;
  result.feedback.forEach(({correct,answer,explanation},index)=>{
   form.querySelector(`#feedback-${index}`).innerHTML=`<div class="feedback ${correct?'correct':'incorrect'}"><strong>${correct?'Верно!':'Пока не получилось'}</strong>${!correct?`Правильный ответ: ${esc(answer)}. `:''}${esc(explanation)}</div>`;
  });
  form.querySelector('#lesson-score').textContent=`${result.right} из ${result.total} верно${result.completed?' · Можно двигаться дальше!':''}`;
  if(result.completed)form.closest('article').querySelector('[data-action="complete-lesson"]').disabled=false;
 }catch(error){toast(error.message);}
 finally{button.disabled=false;}
}

function openTraining(courseId,moduleId){
 const course=getCourse(courseId),module=course?.modules.find(item=>item.id===moduleId);
 if(!module)return;
 quiz={id:uid(),title:module.title,courseId,moduleId,questions:trainingQuestions(module),answers:[],index:0};
 location.hash='#/quiz';
}

async function advanceTraining(form){
 const button=form.querySelector('button[type="submit"]');
 if(button.disabled||!quiz)return;
 const attempt=quiz;
 attempt.answers[attempt.index]=new FormData(form).get('answer0')||'';
 if(attempt.index<attempt.questions.length-1){
  attempt.index++;
  render();
  return;
 }
 button.disabled=true;
 const previous=form.querySelector('[data-action="quiz-back"]');
 previous.disabled=true;
 try{
  const answers=submittedAnswers(attempt.questions,attempt.answers);
  const result=await submitStudy('training',{id:attempt.id,courseId:attempt.courseId,moduleId:attempt.moduleId,answers});
  if(!data.attempts.some(item=>item.id===result.attempt.id)){
   data.attemptCount=(data.attemptCount??data.attempts.length)+1;
   data.attempts.push(result.attempt);
   if(!session.user)persist();
  }
  attempt.result=result;
  if(quiz===attempt&&form.isConnected)location.hash='#/result';
 }catch(error){toast(error.message);}
 finally{button.disabled=false;previous.disabled=attempt.index===0;}
}

document.addEventListener('submit',async e=>{
 const f=e.target;if(f.id==='teacher-form'){e.preventDefault();if(!isOwner())return;const button=f.querySelector('button');button.disabled=true;try{await api('admin/teachers',{method:'POST',body:JSON.stringify({email:new FormData(f).get('email')})});f.reset();await loadTeacherList();toast('Преподаватель добавлен.');}catch(e){toast(e.message);}finally{button.disabled=false;}return;}if(['subject-form','course-form','lesson-form','platform-form'].includes(f.id)&&!canEdit()){e.preventDefault();toast('Требуется вход преподавателя.');return;}if(librarySaving&&['subject-form','course-form','lesson-form','platform-form'].includes(f.id)){e.preventDefault();toast('Дождитесь завершения сохранения.');return;}if(!['lesson-quiz','trainer-quiz','subject-form','course-form','lesson-form','platform-form'].includes(f.id))return;e.preventDefault();
 if(f.id==='lesson-quiz')await checkLesson(f);
 if(f.id==='trainer-quiz')await advanceTraining(f);
 if(f.id==='subject-form'){const v=new FormData(f),s={id:f.dataset.id,title:String(v.get('title')).trim(),desc:String(v.get('desc')).trim(),theme:safeTheme(v.get('theme')),icon:String(v.get('icon')),schools:v.getAll('schools')};if(!s.title||!s.desc||!s.schools.length){toast('Заполни название, описание и выбери хотя бы одну школу.');return;}if(data.subjects.some(x=>x.id!==s.id&&normalize(x.title)===normalize(s.title))){toast('Направление с таким названием уже существует.');return;}if(data.courses.some(c=>c.subject===s.id&&c.schools.some(x=>!s.schools.includes(x)))){toast('В исключённой школе есть курсы этого направления. Сначала измени школы этих курсов.');return;}const idx=data.subjects.findIndex(x=>x.id===s.id);if(idx<0)data.subjects.push(s);else data.subjects[idx]=s;if(!await persistLibrary())return;closeModal();render();toast('Направление сохранено.');}
 if(f.id==='course-form'){captureCourse();const error=validateCourse(draft);if(error){toast(error);return;}const old=getCourse(draft.id),oldFiles=allLessons(old).flatMap(l=>l.attachments||[]),newFiles=new Set(allLessons(draft).flatMap(l=>(l.attachments||[]).map(f=>f.id)));data.courses[data.courses.findIndex(c=>c.id===draft.id)]=structuredClone(draft);const allowed=new Set(allLessons(draft).map(l=>l.id));if(data.progress[draft.id])data.progress[draft.id]=data.progress[draft.id].filter(id=>allowed.has(id));if(await persistLibrary()){for(const file of oldFiles)if(!newFiles.has(file.id))await deleteFile(file.id).catch(()=>{});toast('Курс сохранён. '+(draft.published?'Он виден в каталоге.':'Он пока остаётся черновиком.'));}}
 if(f.id==='lesson-form'){captureLesson();const error=validateLesson(lessonDraft.lesson);if(error){toast(error);return;}const submit=f.querySelector('[type=submit]');submit.disabled=true;try{for(const pending of lessonDraft.pendingFiles){const uploaded=await uploadPdf(pending.file,pending.kind);lessonDraft.lesson.attachments.push(uploaded);}const m=draft.modules.find(m=>m.id===lessonDraft.moduleId),idx=m.lessons.findIndex(l=>l.id===lessonDraft.lesson.id);if(idx<0)m.lessons.push(structuredClone(lessonDraft.lesson));else m.lessons[idx]=structuredClone(lessonDraft.lesson);closeModal();refreshModules();toast('Урок добавлен в черновик. Сохрани курс, чтобы применить изменения.');}catch{toast('Не удалось загрузить PDF. Проверь соединение и права преподавателя.');submit.disabled=false;}}
 if(f.id==='platform-form'){const name=String(new FormData(f).get('name')||'').trim();if(!name){toast('Укажи название платформы.');return;}data.platform=name;if(!await persistLibrary())return;render();toast('Название обновлено.');}
});

document.addEventListener('input',e=>{
 if(e.target.id==='search-global')searchGlobal(e.target.value);
 if(e.target.id==='catalog-query')filterCatalog();
});
function filterCatalog(){const root=document.querySelector('#catalog-results');if(!root)return;root.innerHTML=catalogResults(root.dataset.mode,document.querySelector('#catalog-query').value,document.querySelector('#catalog-school').value,document.querySelector('#catalog-subject').value,document.querySelector('#catalog-level').value);}
document.addEventListener('change',async e=>{
 if(['catalog-school','catalog-subject','catalog-level'].includes(e.target.id))filterCatalog();
 if(['trainer-school','trainer-subject'].includes(e.target.id)){const s=document.querySelector('#trainer-school').value,sub=document.querySelector('#trainer-subject').value;const tmp=document.createElement('div');tmp.innerHTML=trainerContent(s,sub);document.querySelector('#trainer-topics').innerHTML=tmp.querySelector('#trainer-topics').innerHTML;}
 if(e.target.dataset.action==='question-type'){captureLesson();paintLessonEditor();}
 if(['upload-notes','upload-presentation'].includes(e.target.id)){if(!canEdit())return;captureLesson();for(const file of e.target.files){if(file.size>20*1024*1024){toast('Файл больше 20 МБ: '+file.name);continue;}const header=new TextDecoder().decode(await file.slice(0,5).arrayBuffer());if(header!=='%PDF-'){toast('Нужен PDF-файл: '+file.name);continue;}lessonDraft.pendingFiles.push({file,kind:e.target.id==='upload-presentation'?'presentation':'notes'});}paintLessonEditor();}
 if(e.target.id==='import-data'){if(!canEdit())return;const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('Размер JSON не должен превышать 5 МБ.');const incoming=JSON.parse(await file.text());validateImport(incoming);showModal(`${modalHeader('Заменить общую библиотеку?')}<p class="muted">В копии ${incoming.subjects.length} направлений и ${incoming.courses.length} курсов. Общая библиотека сайта будет заменена. Прогресс учеников останется на их устройствах. Файлы из старой локальной версии нужно прикрепить заново.</p><div class="modal-footer"><button class="btn secondary" data-action="close-modal">Отмена</button><button class="btn" data-action="confirm-import" data-import="${esc(JSON.stringify(incoming))}">Импортировать</button></div>`);}catch(err){toast('Не удалось импортировать: '+err.message);}e.target.value='';}
});
function validateImport(d){
 const fail=()=>{throw new Error('Некорректная структура резервной копии.');};
 const str=v=>typeof v==='string'&&v.length<=100000,arr=v=>Array.isArray(v)&&v.length<=2000;
 if(d?.version!==1||!str(d.platform)||!arr(d.subjects)||!arr(d.courses)||!d.progress||typeof d.progress!=='object'||!arr(d.attempts))fail();
 const ids=new Set();const unique=id=>{if(!str(id)||!id||ids.has(id)||id==='__proto__'||id==='constructor'||id==='prototype')fail();ids.add(id);};
 for(const s of d.subjects){unique(s.id);if(!str(s.title)||!str(s.desc)||!str(s.icon)||!arr(s.schools)||s.schools.some(x=>!schools.some(s=>s.id===x))||!Object.hasOwn(themes,s.theme))fail();}
 for(const c of d.courses){unique(c.id);if(!str(c.title)||!str(c.desc)||!str(c.icon)||!str(c.level)||!d.subjects.some(s=>s.id===c.subject)||!arr(c.schools)||c.schools.some(x=>!schools.some(s=>s.id===x))||typeof c.published!=='boolean'||!Object.hasOwn(themes,c.theme)||!arr(c.modules))fail();for(const m of c.modules){unique(m.id);if(!str(m.title)||!arr(m.lessons))fail();for(const l of m.lessons){unique(l.id);if(!str(l.title)||!str(l.theory)||!arr(l.questions)||!arr(l.attachments))fail();for(const q of l.questions){unique(q.id);if(!str(q.text)||!str(q.answer)||!str(q.explanation)||!['choice','text'].includes(q.type)||!arr(q.options)||q.options.some(x=>!str(x))||q.type==='choice'&&(!q.options.includes(q.answer)||q.options.length<2))fail();}for(const f of l.attachments){if(!str(f.id)||!str(f.name)||!['notes','presentation'].includes(f.kind))fail();}}}}
 for(const [key,value] of Object.entries(d.progress))if(!arr(value)||value.some(x=>!str(x))||!d.courses.some(c=>c.id===key))fail();
 for(const a of d.attempts)if(!str(a.title)||!str(a.date)||!Number.isFinite(a.right)||!Number.isFinite(a.total)||a.total<1||a.right<0||a.right>a.total||Number.isNaN(Date.parse(a.date)))fail();
}
window.addEventListener('beforeunload',e=>{if(draft&&route()[0]==='admin'&&route()[1]==='edit'){captureCourse();if(JSON.stringify(draft)!==JSON.stringify(getCourse(draft.id))){e.preventDefault();e.returnValue='';}}});
async function bootstrap(){
 app.innerHTML='<div class="container"><div class="empty" style="margin-top:60px">Открываем библиотеку…</div></div>';
 try{
  const old=structuredClone(data);
  if(previousLocalLibrary&&!old.serverManaged&&!localStorage.getItem('orbita-before-server-v1'))localStorage.setItem('orbita-before-server-v1',previousLocalLibrary);
  const remote=await loadLibrary();
  Object.assign(data,remote,{serverManaged:true});
  studyProfileUnavailable=false;
  if(session.user){
   Object.assign(data,{progress:{},attempts:[],attemptCount:0});
   try{Object.assign(data,await api('learning'));}
   catch{studyProfileUnavailable=true;}
  }else{
   const guest=loadData();
   Object.assign(data,{progress:guest.progress,attempts:guest.attempts,attemptCount:undefined});
   if(!old.serverManaged){
    for(const course of data.courses){
     const previous=old.courses.find(item=>item.id===course.id);
     if(!previous)continue;
     const titles=new Set(allLessons(previous).filter(lesson=>old.progress[course.id]?.includes(lesson.id)).map(lesson=>lesson.title));
     data.progress[course.id]=allLessons(course).filter(lesson=>titles.has(lesson.title)).map(lesson=>lesson.id);
    }
   }
  }
  cacheData();render();
 }catch(e){app.innerHTML=`<div class="container"><div class="empty" style="margin-top:60px"><h1 style="font-size:28px">Не удалось открыть библиотеку</h1><p>${esc(e.message)}</p><button class="btn" data-action="reload-library">Повторить</button></div></div>`;}
}
window.addEventListener('teacher-access-changed',()=>{draft=null;closeModal();if(route()[0]==='admin')render();});
bootstrap();
